CREATE TABLE `categorias` (
  `idCategoria` int(11) NOT NULL,
  `Nombre` varchar(45) NOT NULL,
  `Descripcion` varchar(1000) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Volcado de datos para la tabla `categorias`
--

INSERT INTO `categorias` (`idCategoria`, `Nombre`, `Descripcion`) VALUES
(1, 'Programación/Testing', 'La programación va más allá que cualquier idioma, pues también es un gran tutor cuando se trata de aprender a solucionar problemas, principalmente situaciones de lógica e ingenio. Es el arte de crear soluciones desde cero a paradigmas complejos a base de un pensamiento estructurado, lógico y creativo. El objetivo del testing no solo es encontrar fallas sino también aumentar la confianza en la calidad del producto, facilitar información para la toma de decisiones y detectar oportunidades de mejora.'),
(2, 'Datos', 'Son bases de datos únicamente de lectura, utilizadas principalmente para almacenar datos históricos que posteriormente se pueden utilizar para estudiar el comportamiento de un conjunto de datos a través del tiempo, realizar proyecciones, tomar decisiones y realizar análisis de datos para inteligencia empresarial.'),
(3, 'Marketing/Negocios', 'Estudiar Marketing te da ventajas porque tiene una amplia salida laboral y te permite obtener títulos intermedios para que puedas insertarte rápidamente en el mercado laboral. Como es una disciplina en constante interacción con el medio, te mantenés siempre al tanto de las novedades.'),
(4, 'Diseño', 'El diseño gráfico ha servido para mejorar y transformar el mundo donde vivimos, y es que se volvió parte de nuestro día a día, ya que, cada producto que utilizamos tiene un color, una letra, una forma y todo salió de la mente de un diseñador que plasmo un arte sobre esos productos.'),
(5, 'Infraestructuras', 'La infraestructura TI es una de las bases para el correcto funcionamiento de una empresa. Es importante tener unos conocimientos básicos y estar en constante actualización. Otro de los aspectos importantes que conforman la infraestructura TI es el mantenimiento y la forma de guardar la información.'),
(6, 'Productividad', 'La función de metodologías ágiles es encontrar formas de trabajar se amolden a las condiciones de los proyectos, dar más flexibilidad a los procesos y adaptarlos a las necesidades específicas de cada equipo de trabajo.'),
(7, 'Ofimática', 'El proceso de ofimática cobra importancia porque se basa en la creación, manipulación, transmisión y almacenamiento de la información de una oficina. La ofimática llegó a las empresas para aumentar la productividad laboral y así compartir con mayor agilidad lo que antes se hacía de forma manual.'),
(9, 'Robotica', 'Cursos de robotica con arduino'),
(10, 'Impresion 3D', 'Cursos de impresion 3D');

