INSERT INTO `cursos` (`idCurso`, `Nombre`, `Descripcion`, `Camada`, `idCategoria`, `Imagen`) VALUES
(1, 'PHP', 'Comienza con el curso Programación Web en PHP y MySQL. Domina las herramientas necesarias para crear tu sitio en internet. Haz tus primeros pasos como Web Developer aprendiendo la tecnología más eficaz para ello.', 3, 1, ),
(2, 'Introducción a Base de Datos y MySQL.', 'Domina los fundamentos para el manejo y la manipulación de datos. Conoce el mundo de las bases de datos para entender cómo trabajar con ellas.', 2, 2, );
INSERT INTO `cursos` (`idCurso`, `Nombre`, `Descripcion`, `Camada`, `idCategoria`, `Imagen`) VALUES
(3, 'Introducción al Marketing Digital', 'Domina los principales conceptos del Marketing Digital y el Inbound Marketing. Desarrolla una planificación que optimice los distintos canales digitales.', 2, 3, );
INSERT INTO `cursos` (`idCurso`, `Nombre`, `Descripcion`, `Camada`, `idCategoria`, `Imagen`) VALUES
(5, 'Diseño UI/UX', 'Potencia tus sitios web comprendiendo la importancia de la usabilidad. Aprende cómo diseñar experiencias digitales en tus proyectos.', 2, 4, ),
(6, 'Word Intermedio', 'Aprende a utilizar un procesador de texto. Domina por completo Word, crea índices, esquemas, columnas, tablas, currículums y cartas de presentación. Aprende a combinar correspondencia junto con las herramientas más utilizadas en el ambiente administrativo.', 1, 7, );
INSERT INTO `cursos` (`idCurso`, `Nombre`, `Descripcion`, `Camada`, `idCategoria`, `Imagen`) VALUES
(7, 'PHP Avanzado', 'Curso dirigido a los que quieren seguir avanzando en el mundo de php', 2, 1, );
INSERT INTO `cursos` (`idCurso`, `Nombre`, `Descripcion`, `Camada`, `idCategoria`, `Imagen`) VALUES
(8, 'React JS', 'Curso dirigido a los que tiene base en html, css y js', 1, 1, );
